CREATE TABLE IF NOT EXISTS verdicts (id INTEGER PRIMARY KEY AUTOINCREMENT, safe TEXT NOT NULL, nonce INTEGER NOT NULL, to_addr TEXT NOT NULL, value TEXT NOT NULL, selector TEXT NOT NULL, verdict TEXT NOT NULL, reasons TEXT NOT NULL, at INTEGER NOT NULL);
CREATE INDEX IF NOT EXISTS verdicts_at ON verdicts (at);
CREATE INDEX IF NOT EXISTS verdicts_safe ON verdicts (safe, at);
CREATE TABLE IF NOT EXISTS usage (safe TEXT NOT NULL, day TEXT NOT NULL, n INTEGER NOT NULL, PRIMARY KEY (safe, day));
CREATE TABLE IF NOT EXISTS counts (verdict TEXT PRIMARY KEY, n INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS charters (safe TEXT PRIMARY KEY, version TEXT NOT NULL, lists TEXT NOT NULL, tx TEXT, at INTEGER NOT NULL);
